func TestCursorAgent_ResolveSessionFile_NestedLayout(t *testing.T) {
	t.Parallel()
	ag := &CursorAgent{}
	// When nested dir and file exist, returns nested path (IDE pattern)
	tmpDir := t.TempDir()
	nestedDir := filepath.Join(tmpDir, "abc123")
