// Package codex implements the Agent interface for OpenAI's Codex CLI.
package codex

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/validation"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameCodex, NewCodexAgent)
}

// CodexAgent implements the Agent interface for OpenAI's Codex CLI.
//
//nolint:revive // CodexAgent is clearer than Agent in this context
type CodexAgent struct {
	CommandRunner agent.TextCommandRunner
}

// NewCodexAgent creates a new Codex agent instance.
func NewCodexAgent() agent.Agent {
	return &CodexAgent{}
}

// Name returns the agent registry key.
func (c *CodexAgent) Name() types.AgentName {
	return agent.AgentNameCodex
}

// Type returns the agent type identifier.
func (c *CodexAgent) Type() types.AgentType {
	return agent.AgentTypeCodex
}

// Description returns a human-readable description.
func (c *CodexAgent) Description() string {
	return "Codex - OpenAI's CLI coding agent"
}

// IsPreview returns true because this is a new integration.
func (c *CodexAgent) IsPreview() bool { return true }

// DetectPresence checks if Codex is configured in the repository.
func (c *CodexAgent) DetectPresence(ctx context.Context) (bool, error) {
	return c.AreHooksInstalled(ctx), nil
}

// GetSessionID extracts the session ID from hook input.
func (c *CodexAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// resolveCodexHome returns the Codex home directory (CODEX_HOME or ~/.codex).
func resolveCodexHome() (string, error) {
	if codexHome := os.Getenv("CODEX_HOME"); codexHome != "" {
		return codexHome, nil
	}
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}
	return filepath.Join(homeDir, ".codex"), nil
}

// GetSessionDir returns the directory where Codex stores session transcripts.
// Codex stores transcripts under CODEX_HOME/sessions/YYYY/MM/DD/.
func (c *CodexAgent) GetSessionDir(_ string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_CODEX_SESSION_DIR"); override != "" {
		return override, nil
	}
	codexHome, err := resolveCodexHome()
	if err != nil {
		return "", err
	}
	return filepath.Join(codexHome, "sessions"), nil
}

// ResolveSessionFile returns the path to a Codex session transcript file.
// Codex provides the transcript path directly in hook payloads as an absolute
// path, but that path is recorded as SessionRef and read directly — it never
// round-trips through this function. When only a session ID is available,
// attach/rewind must recover it from the
// sessions/YYYY/MM/DD/rollout-...-<session-id>.jsonl layout.
//
// An absolute agentSessionID is rejected with an error rather than returned
// verbatim: that would let an attacker-influenceable session ID (e.g. from
// checkpoint metadata) resolve to an arbitrary path and, via the
// resume/rewind write path, overwrite files outside the session directory.
func (c *CodexAgent) ResolveSessionFile(sessionDir, agentSessionID string) (string, error) {
	if filepath.IsAbs(agentSessionID) {
		return "", fmt.Errorf("session ID must be relative, got absolute path: %q", agentSessionID)
	}
	if path := findRolloutBySessionID(sessionDir, agentSessionID); path != "" {
		return path, nil
	}
	if sessionDir != "" {
		return filepath.Join(sessionDir, agentSessionID+".jsonl"), nil
	}
	return agentSessionID, nil
}

// ResolveRestoredSessionFile returns the canonical Codex rollout path for a
// restored session so `codex resume <id>` can rediscover it.
func (c *CodexAgent) ResolveRestoredSessionFile(sessionDir, agentSessionID string, transcript []byte) (string, error) {
	if err := validation.ValidateAgentSessionID(agentSessionID); err != nil {
		return "", fmt.Errorf("validate agent session ID: %w", err)
	}
	startTime, err := parseSessionStartTime(transcript)
	if err != nil {
		return "", fmt.Errorf("parse session start time: %w", err)
	}
	return restoredRolloutPath(sessionDir, agentSessionID, startTime), nil
}

// ProtectedDirs returns directories that Codex uses for config/state.
func (c *CodexAgent) ProtectedDirs() []string { return []string{".codex"} }

// ReadSession reads a session from Codex's storage (JSONL rollout file).
func (c *CodexAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	startTime, err := parseSessionStartTime(data)
	if err != nil {
		return nil, fmt.Errorf("failed to parse session start time: %w", err)
	}

	// Extract modified files from the rollout transcript (best-effort, deduplicated).
	var modifiedFiles []string
	seen := make(map[string]struct{})
	for _, lineData := range splitJSONL(data) {
		for _, f := range extractFilesFromLine(lineData) {
			if _, exists := seen[f]; !exists {
				seen[f] = struct{}{}
				modifiedFiles = append(modifiedFiles, f)
			}
		}
	}

	return &agent.AgentSession{
		SessionID:     input.SessionID,
		AgentName:     c.Name(),
		SessionRef:    input.SessionRef,
		StartTime:     startTime,
		NativeData:    data,
		ModifiedFiles: modifiedFiles,
	}, nil
}

// WriteSession writes a session to Codex's storage (JSONL rollout file).
func (c *CodexAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}

	if session.AgentName != "" && session.AgentName != c.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	dataToWrite := sanitizeRestoredTranscript(session.NativeData)
	if err := os.WriteFile(session.SessionRef, dataToWrite, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// FormatResumeCommand returns the command to resume a Codex session.
func (c *CodexAgent) FormatResumeCommand(sessionID string) string {
	return "codex resume " + sessionID
}

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (c *CodexAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits a JSONL transcript at line boundaries.
func (c *CodexAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (c *CodexAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

func restoredRolloutPath(codexHome, agentSessionID string, startTime time.Time) string {
	timestamp := startTime.UTC()
	datePath := filepath.Join(
		codexHome,
		timestamp.Format("2006"),
		timestamp.Format("01"),
		timestamp.Format("02"),
	)
	filename := fmt.Sprintf("rollout-%s-%s.jsonl", timestamp.Format("2006-01-02T15-04-05"), agentSessionID)
	return filepath.Join(datePath, filename)
}

// LaunchCmd builds an exec.Cmd for `codex "<initialPrompt>"`. Stdio is wired
// to the caller's TTY so the agent runs foreground and the user interacts
// normally. The call site is expected to Run() and wait. Hooks inherit the
// parent environment.
func (c *CodexAgent) LaunchCmd(ctx context.Context, initialPrompt string) (*exec.Cmd, error) {
	bin, err := exec.LookPath("codex")
	if err != nil {
		return nil, fmt.Errorf("codex binary not on PATH: %w", err)
	}
	cmd := exec.CommandContext(ctx, bin, initialPrompt)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Env = os.Environ()
	return cmd, nil
}

func findRolloutBySessionID(codexHome, agentSessionID string) string {
	if codexHome == "" || validation.ValidateAgentSessionID(agentSessionID) != nil {
		return ""
	}

	patterns := []string{
		filepath.Join(codexHome, "rollout-*-"+agentSessionID+".jsonl"),
		filepath.Join(codexHome, "*", "*", "*", "rollout-*-"+agentSessionID+".jsonl"),
		filepath.Join(filepath.Dir(codexHome), "archived_sessions", "*", "*", "*", "rollout-*-"+agentSessionID+".jsonl"),
	}
	for _, pattern := range patterns {
		matches, err := filepath.Glob(pattern)
		if err != nil || len(matches) == 0 {
			continue
		}
		// Multiple restored rollouts for the same session ID can exist. Return the
		// lexicographically latest path so newer dated restores win deterministically.
		sort.Strings(matches)
		return matches[len(matches)-1]
	}

	return ""
}

// Package cursor implements the Agent interface for Cursor.
package cursor

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// Compile-time interface assertion.
var _ agent.TranscriptPreparer = (*CursorAgent)(nil)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameCursor, NewCursorAgent)
}

// CursorAgent implements the Agent interface for Cursor.
//
//nolint:revive // CursorAgent is clearer than Agent in this context
type CursorAgent struct {
	CommandRunner agent.TextCommandRunner
}

// NewCursorAgent creates a new Cursor agent instance.
func NewCursorAgent() agent.Agent {
	return &CursorAgent{}
}

// Name returns the agent registry key.
func (c *CursorAgent) Name() types.AgentName {
	return agent.AgentNameCursor
}

// Type returns the agent type identifier.
func (c *CursorAgent) Type() types.AgentType {
	return agent.AgentTypeCursor
}

// Description returns a human-readable description.
func (c *CursorAgent) Description() string {
	return "Cursor - AI-powered code editor"
}

func (c *CursorAgent) IsPreview() bool { return true }

// DetectPresence checks if Cursor is configured in the repository.
func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		worktreeRoot = "."
	}

	cursorDir := filepath.Join(worktreeRoot, ".cursor")
	if _, err := os.Stat(cursorDir); err == nil {
		return true, nil
	}
	return false, nil
}

// GetSessionID extracts the session ID from hook input.
func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// ResolveSessionFile returns the path to a Cursor session file.
// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
// We prefer nested if the file OR directory exists (the directory may be created
// before the file is flushed), otherwise fall back to flat.
func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) (string, error) {
	nestedDir := filepath.Join(sessionDir, agentSessionID)
	nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
	if _, err := os.Stat(nested); err == nil {
		return nested, nil
	}
	// IDE creates the directory before the transcript file — predict nested path.
	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
		return nested, nil
	}
	return filepath.Join(sessionDir, agentSessionID+".jsonl"), nil
}

// ProtectedDirs returns directories that Cursor uses for config/state.
func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }

// GetSessionDir returns the directory where Cursor stores session transcripts.
func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
		return override, nil
	}

	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}

	projectDir := sanitizePathForCursor(repoPath)
	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
}

// GetSessionBaseDir returns the base directory containing per-project session subdirectories.
// Unlike GetSessionDir, this does NOT use test overrides because the override
// points to a specific project dir, not the base containing all projects.
func (c *CursorAgent) GetSessionBaseDir() (string, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}
	return filepath.Join(homeDir, ".cursor", "projects"), nil
}

// ReadSession reads a session from Cursor's storage (JSONL transcript file).
// Note: ModifiedFiles is left empty because Cursor's transcript does not contain
// tool_use blocks for file detection. TranscriptAnalyzer extracts prompts and
// summaries; file detection relies on git status.
func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	return &agent.AgentSession{
		SessionID:  input.SessionID,
		AgentName:  c.Name(),
		SessionRef: input.SessionRef,
		StartTime:  time.Now(),
		NativeData: data,
	}, nil
}

// PrepareTranscript waits for Cursor's transcript file to be flushed to disk.
// Cursor writes transcripts asynchronously; during mid-turn commits the file
// may not yet contain data. This polls until the file exists and is non-empty,
// or until the timeout expires.
func (c *CursorAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
	const (
		maxWait      = 5 * time.Second
		pollInterval = 50 * time.Millisecond
	)

	logCtx := logging.WithComponent(ctx, "agent.cursor")

	start := time.Now()
	deadline := start.Add(maxWait)
	if ctxDeadline, ok := ctx.Deadline(); ok && ctxDeadline.Before(deadline) {
		deadline = ctxDeadline
	}
	effectiveTimeout := deadline.Sub(start)

	for time.Now().Before(deadline) {
		if err := ctx.Err(); err != nil {
			return fmt.Errorf("context ended while waiting for transcript: %w", err)
		}

		info, err := os.Stat(sessionRef)
		if err == nil {
			if info.Size() > 0 {
				logging.Debug(logCtx, "transcript file ready",
					slog.Int64("size", info.Size()),
				)
				return nil
			}
		} else if !os.IsNotExist(err) {
			return fmt.Errorf("failed to stat transcript %q: %w", sessionRef, err)
		}

		wait := pollInterval
		if remaining := time.Until(deadline); remaining < wait {
			wait = remaining
		}
		timer := time.NewTimer(wait)
		select {
		case <-ctx.Done():
			if !timer.Stop() {
				<-timer.C
			}
			return fmt.Errorf("context ended while waiting for transcript: %w", ctx.Err())
		case <-timer.C:
		}
	}

